changeSet.sql:
INSERT INTO permissions (name, description) VALUES ('plugin_netfilter_access', 'Access to network filter plugin');
INSERT INTO userrolepermissions (roleId, permissionId)
    SELECT id, currval('permissions_id_seq')
    FROM userroles;

CREATE TABLE plugin_netfilter_profile_config (
    profileId INT NOT NULL,
    configurationId INT NOT NULL,
    CONSTRAINT plugin_nf_pc_pk PRIMARY KEY (profileId, configurationId),
    CONSTRAINT plugin_nf_pc_profile_fk FOREIGN KEY (profileId) REFERENCES plugin_netfilter_profile(id) ON DELETE CASCADE,
    CONSTRAINT plugin_nf_pc_config_fk FOREIGN KEY (configurationId) REFERENCES configurations(id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE INDEX plugin_nf_pc_config_idx ON plugin_netfilter_profile_config (configurationId);
